package server

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The fixture is committed next to this test (go/testdata/http) and is regenerated by
// scripts/go-rewrite/record/record-http.mjs from packages/server/src/http.ts. The static root
// is resolved relative to the package directory so the test needs no env plumbing.
const (
	recordedFile     = "../../testdata/http/requests.json"
	recordedFixtures = "../../testdata/http/static-root"
)

// recordedCase mirrors one entry of requests.json.
type recordedCase struct {
	Group      string            `json:"group"`
	Method     string            `json:"method"`
	Path       string            `json:"path"`
	Status     int               `json:"status"`
	Headers    map[string]string `json:"headers"`
	BodyBytes  int               `json:"bodyBytes"`
	BodySHA256 string            `json:"bodySha256"`
}

type recordedFileData struct {
	Version        int            `json:"version"`
	IgnoredHeaders []string       `json:"ignoredHeaders"`
	Cases          []recordedCase `json:"cases"`
	Note           string         `json:"-"`
	FixtureRoot    string         `json:"-"`
}

func loadRecorded(t *testing.T) recordedFileData {
	t.Helper()
	raw, err := os.ReadFile(filepath.FromSlash(recordedFile))
	if err != nil {
		t.Fatalf("read %s: %v (regenerate with scripts/go-rewrite/record/record-http.mjs)", recordedFile, err)
	}
	var data recordedFileData
	if err := json.Unmarshal(raw, &data); err != nil {
		t.Fatalf("parse %s: %v", recordedFile, err)
	}
	if data.Version != 1 {
		t.Fatalf("recorded file version = %d, want 1", data.Version)
	}
	if len(data.Cases) == 0 {
		t.Fatalf("%s contains no cases", recordedFile)
	}
	return data
}

// applyRecordedEnv sets exactly the variables the recorder's group used and clears the others,
// so a stray value in the test process environment cannot change the comparison.
//
// NEX_SERVER_ID is always set: without it the response carries os.hostname(), which would make
// the fixture unreproducible off the recording machine.
func applyRecordedEnv(t *testing.T, group string) {
	t.Helper()
	for _, key := range []string{"NEX_SERVER_ID", "NEX_SERVER_NAME", "NEX_SERVER_WORKSPACE", "NEX_SERVER_TOKEN"} {
		t.Setenv(key, "")
	}
	switch group {
	case "plain":
		t.Setenv("NEX_SERVER_ID", "record-plain")
	case "named":
		t.Setenv("NEX_SERVER_ID", "record-named")
		t.Setenv("NEX_SERVER_NAME", "Recorded Server")
		t.Setenv("NEX_SERVER_WORKSPACE", "/srv/demo")
	case "token":
		t.Setenv("NEX_SERVER_ID", "record-token")
		t.Setenv("NEX_SERVER_TOKEN", "record-token-value")
	default:
		t.Fatalf("unknown recorded group %q", group)
	}
}

func recordedHandler(t *testing.T) http.Handler {
	t.Helper()
	handler, _, err := NewHandler(Options{StaticRoot: filepath.FromSlash(recordedFixtures), SPAFallback: true})
	if err != nil {
		t.Fatalf("NewHandler: %v", err)
	}
	return handler
}

// TestStaticAndServerInfoMatchRecordedTypeScript compares every recorded Node response against
// the Go handler: status, all recorded headers, body length and body SHA-256.
//
// Date and Server are absent from the recording (see record-http.mjs) and the connection
// header is transport, so neither is compared. A mismatch means the Go port is observably
// different from the server the desktop and browser talk to today.
func TestStaticAndServerInfoMatchRecordedTypeScript(t *testing.T) {
	data := loadRecorded(t)

	for _, testCase := range data.Cases {
		t.Run(testCase.Group+"_"+testCase.Method+"_"+testCase.Path, func(t *testing.T) {
			applyRecordedEnv(t, testCase.Group)
			// Go resolves the env at construction and Node re-reads it per request for
			// server-info, so the handler is built after the group's env is in place.
			handler := recordedHandler(t)

			request := httptest.NewRequest(testCase.Method, escapeForGoRequest(testCase.Path), nil)
			recorder := httptest.NewRecorder()
			handler.ServeHTTP(recorder, request)

			if recorder.Code != testCase.Status {
				t.Errorf("status = %d, want %d", recorder.Code, testCase.Status)
			}
			body := recorder.Body.Bytes()
			if len(body) != testCase.BodyBytes {
				t.Errorf("body length = %d, want %d", len(body), testCase.BodyBytes)
			}
			sum := sha256.Sum256(body)
			if got := hex.EncodeToString(sum[:]); got != testCase.BodySHA256 {
				t.Errorf("body sha256 = %s, want %s", got, testCase.BodySHA256)
			}
			for name, want := range testCase.Headers {
				if got := recorder.Header().Get(name); got != want {
					t.Errorf("header %s = %q, want %q", name, got, want)
				}
			}
		})
	}
}

// escapeForGoRequest re-encodes the '%' characters that url.Parse refuses.
//
// httptest.NewRequest builds a url.URL from the string, and url.Parse rejects a '%' that is
// not followed by two hex digits. Encoding only those keeps every recorded target — including
// the encoded traversal forms, which all use valid escapes — byte-identical to what Node's
// HTTP server saw on the wire.
func escapeForGoRequest(path string) string {
	var escaped strings.Builder
	for i := 0; i < len(path); i++ {
		if path[i] == '%' && !hasHexPairAt(path, i) {
			escaped.WriteString("%25")
			continue
		}
		escaped.WriteByte(path[i])
	}
	return escaped.String()
}

func hasHexPairAt(path string, at int) bool {
	if at+2 >= len(path) {
		return false
	}
	for i := at + 1; i <= at+2; i++ {
		c := path[i]
		isHex := (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
		if !isHex {
			return false
		}
	}
	return true
}
